"use client";

import { useEffect, useState, type FormEvent } from "react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { logout } from "@/lib/actions";

interface Me {
  id: number;
  name: string;
  email: string;
  balance: number;
}

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState("");
  const [savedMsg, setSavedMsg] = useState<string | null>(null);
  const [me, setMe] = useState<Me | null>(null);
  const router = useRouter();

  useEffect(() => {
    let alive = true;
    fetch("/api/me")
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => {
        if (alive && d?.user) setMe(d.user);
      })
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, []);

  const submitSearch = (e: FormEvent) => {
    e.preventDefault();
    const keyword = q.trim();
    setOpen(false);
    if (!keyword) {
      router.push("/compare");
      return;
    }
    router.push(`/compare?q=${encodeURIComponent(keyword)}`);
  };

  const showSaved = () => {
    if (me) {
      router.push("/dashboard");
      return;
    }
    setSavedMsg("Saved items akan tersedia setelah login.");
    setTimeout(() => setSavedMsg(null), 2200);
  };

  return (
    <>
      <header className="navbar">
        <Link className="brand" href="/">
          <Image
            className="brand-mark"
            src="/logo-choicelens.png"
            alt="ChoiceLens"
            width={33}
            height={35}
          />
          <span>
            Choice<span>Lens</span>
          </span>
        </Link>

        <nav
          className="nav-links"
          aria-label="Main navigation"
          data-open={open ? "true" : "false"}
          style={
            open
              ? {
                  display: "flex",
                  position: "absolute",
                  top: 70,
                  left: 0,
                  right: 0,
                  margin: "0 12px",
                  padding: 18,
                  flexDirection: "column",
                  background: "#fff",
                  border: "1px solid #e2e8f0",
                  borderRadius: 14,
                  boxShadow: "0 12px 30px rgba(15,23,42,.1)",
                  gap: 16,
                }
              : undefined
          }
          onClick={() => setOpen(false)}
        >
          <Link href="/category/smartphones">Smartphones</Link>
          <Link href="/category/laptops">Laptops</Link>
          <Link href="/category/shoes">Basketball Shoes</Link>
          <Link href="/compare">Compare</Link>
          <Link href="/learn">Learn</Link>
        </nav>

        <div className="nav-actions">
          <form
            onSubmit={submitSearch}
            style={{ display: "flex", alignItems: "center" }}
          >
            <input
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="Search..."
              aria-label="Search comparisons"
              style={{
                width: 110,
                border: "1px solid #e2e8f0",
                borderRadius: 10,
                padding: "6px 10px",
                fontSize: 12,
                outline: "none",
              }}
            />
            <button
              className="icon-btn"
              aria-label="Search"
              type="submit"
              title="Cari"
            >
              ⌕
            </button>
          </form>
          <button
            className="icon-btn saved-btn"
            aria-label="Saved"
            onClick={showSaved}
            type="button"
          >
            ♥
          </button>
          {me ? (
            <>
              <Link
                href="/topup"
                title="Topup token"
                style={{
                  fontSize: 11,
                  fontWeight: 800,
                  color: "#166534",
                  background: "#f0fdf4",
                  border: "1px solid #bbf7d0",
                  borderRadius: 10,
                  padding: "6px 10px",
                  textDecoration: "none",
                  whiteSpace: "nowrap",
                }}
              >
                🎟 {me.balance}
              </Link>
              <Link
                href="/dashboard"
                className="profile-btn"
                aria-label="Dashboard"
                title={me.email}
                style={{
                  textDecoration: "none",
                  display: "grid",
                  placeItems: "center",
                }}
              >
                {me.name.slice(0, 1).toUpperCase()}
              </Link>
              <form action={logout}>
                <button
                  type="submit"
                  aria-label="Logout"
                  title="Keluar"
                  style={{
                    border: "1px solid #e2e8f0",
                    background: "#fff",
                    borderRadius: 10,
                    padding: "6px 10px",
                    fontSize: 11,
                    fontWeight: 800,
                    color: "#64748b",
                  }}
                >
                  Keluar
                </button>
              </form>
            </>
          ) : (
            <Link
              href="/login"
              style={{
                fontSize: 11,
                fontWeight: 800,
                color: "#fff",
                background: "#2563eb",
                borderRadius: 10,
                padding: "8px 14px",
                textDecoration: "none",
                whiteSpace: "nowrap",
              }}
            >
              Masuk
            </Link>
          )}
        </div>

        <button
          className="menu-btn"
          aria-label="Open menu"
          onClick={() => setOpen((v) => !v)}
        >
          ☰
        </button>
      </header>
      <div className={`toast${savedMsg ? " show" : ""}`}>{savedMsg ?? ""}</div>
    </>
  );
}
